CREATE TABLE IF NOT EXISTS gis_authoritative_crosswalk (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version text NOT NULL, source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE, target_feature_id uuid REFERENCES gis_spatial_features(id) ON DELETE SET NULL, status text NOT NULL, confidence text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,source_feature_id));
CREATE INDEX IF NOT EXISTS idx_gis_authoritative_crosswalk_version ON gis_authoritative_crosswalk(crosswalk_version,status);